{
    "id": "https://almanak.github.io/schemas/events.aarhusteater.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "events.aarhusteater",
    "description": "Schema for all plays at Aarhus Teater. Must extend the generic people-schema.",
    "type": "object",
    "_meta": {
        "indexProperties": [
            "id",
            "domain",
            "schema",
            "from_date",
            "to_date"
        ],
        "systemProperties": [
            "uuid",
            "id",
            "domain",
            "schema",
            "scheme",
            "created",
            "created_by",
            "updated",
            "updated_by",
            "ext_data.scope",
            "status"
        ],
        "fulltextProperties": [
            "description"
        ],
        "autocompleteProperties": [
            "display_label"
        ]
    },
    "properties": {
        "uuid": {
            "type": "string",
            "title": "Universal unique identifier",
            "description": "UUID1. Assigned by system",
            "pattern": "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
        },
        "id": {
            "type": "string",
            "title": "Resourcespecifik ID",
            "description": "9-cifret l\u00f8benummer semi-specifik for resourcetypen. Assigned by system",
            "pattern": "^[0-9]+$"
        },
        "domain": {
            "type": "string",
            "enum": [
                "records",
                "people",
                "organisations",
                "families",
                "events",
                "places",
                "concepts",
                "things"
            ],
            "title": "Resourcetype",
            "description": "S\u00e6ttes kun n\u00e5r der v\u00e6lges skema til oprettelse. Ellers fastsat."
        },
        "schema": {
            "type": "string",
            "title": "Skema",
            "description": "S\u00e6ttes kun n\u00e5r der v\u00e6lges skema til oprettelse. Ellers fastsat."
        },
        "created": {
            "type": "string",
            "format": "date-time",
            "title": "Skabt",
            "description": "Datetime for skabelse af metadata-ressourcen"
        },
        "created_by": {
            "type": "string",
            "maxLength": 255,
            "title": "Skabt af",
            "description": "Brugernavn/ID p\u00e5 skaber/oploader af metadata-ressourcen"
        },
        "updated": {
            "type": "string",
            "format": "date-time",
            "title": "Senest opdateret",
            "description": "Datetime for seneste opdatering af ressourcen"
        },
        "updated_by": {
            "type": "string",
            "maxLength": 255,
            "title": "Senest opdateret af",
            "description": "Brugernavn p\u00e5 seneste opdaterer af metadata-ressourcen"
        },
        "status": {
            "type": "string",
            "enum": [
                "validated",
                "machine-generated",
                "user-generated"
            ],
            "title": "Status",
            "default": "user-generated"
        },
        "name": {
            "type": "string",
            "maxLength": 255,
            "title": "Forestillingsnavn",
            "description": "Navnet p\u00e5 forestillingen (uden \u00e5rstal)"
        },
        "display_label": {
            "type": "string",
            "maxLength": 255,
            "title": "Displaynavn",
            "description": "Den label, som entiteten repr\u00e6senteres med"
        },
        "description": {
            "type": "string",
            "maxLength": 5000,
            "title": "Beskrivelse"
        },
        "sources": {
            "type": "string",
            "title": "Kilder",
            "description": "URL-links eller enkeltlinje referencer"
        },
        "portrait": {
            "type": "string",
            "maxLength": 255,
            "format": "uri",
            "title": "Portr\u00e6t"
        },
        "date_from": {
            "type": "string",
            "format": "date",
            "title": "F\u00f8dselsdato (\u00e5\u00e5\u00e5\u00e5-mm-dd)",
            "pattern": "^([0-9]{4})(-([0-9]{2}))?(-([0-9]{2}))?$"
        },
        "date_to": {
            "type": "string",
            "format": "date",
            "title": "D\u00f8dsdato (\u00e5\u00e5\u00e5\u00e5-mm-dd)",
            "pattern": "^([0-9]{4})(-([0-9]{2}))?(-([0-9]{2}))?$"
        },
        "ext_data": {
            "type": "object",
            "title": "Udvided metadata",
            "properties": {
                "original_id": {
                    "type": "string",
                    "title": "Originalt ID"
                },
                "poster": {
                    "type": "boolean",
                    "title": "Plakat"
                },
                "stagename": {
                    "type": "string",
                    "title": "Scene"
                },
                "composer": {
                    "type": "string",
                    "title": "Komponist"
                },
                "translater": {
                    "type": "string",
                    "title": "Overs\u00e6tter"
                },
                "publisher": {
                    "type": "string",
                    "title": "Udgiver"
                },
                "programme": {
                    "type": "boolean",
                    "title": "Program"
                },
                "season": {
                    "type": "string",
                    "title": "S\u00e6son"
                },
                "playwright": {
                    "type": "string",
                    "title": "Forfatter"
                },
                "director": {
                    "type": "string",
                    "title": "Instrukt\u00f8r"
                },
                "scenographer": {
                    "type": "string",
                    "title": "Scenograf"
                }
            }
        }
    }
}

