{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "definitions": {
        "positiveNumber": {
            "type": "number",
            "minimum": 0
        },
        "returnTipHeightRange": {
            "type": "number",
            "minimum": 0.25,
            "maximum": 1.25
        },
        "idleCurrentRange": {
            "type": "number",
            "minimum": 0.01,
            "maximum": 1.0
        },
        "xyzArray": {
            "type": "array",
            "description": "Array of 3 numbers, [x, y, z]",
            "items": {
                "type": "number"
            },
            "minItems": 3,
            "maxItems": 3
        },
        "linearEquations": {
            "description": "Array containing any number of 3-arrays. Each inner 3-array describes a line segment: [boundary, slope, intercept]. So [1, 2, 3] would mean 'where (next_boundary > x >= 1), y = 2x + 3'",
            "type": "array",
            "items": {
                "type": "array",
                "items": {
                    "type": "number"
                },
                "minItems": 3,
                "maxItems": 3
            }
        },
        "liquidHandlingSpecs": {
            "description": "Object containing linear equations for translating between uL of liquid and mm of plunger travel. There is one linear equation for aspiration and one for dispense",
            "type": "object",
            "required": [
                "aspirate",
                "dispense"
            ],
            "additionalProperties": false,
            "properties": {
                "aspirate": {
                    "$ref": "#/definitions/linearEquations"
                },
                "dispense": {
                    "$ref": "#/definitions/linearEquations"
                }
            }
        },
        "editConfigurations": {
            "type": "object",
            "description": "Object allowing you to modify a config",
            "required": [
                "value"
            ],
            "properties": {
                "value": {
                    "type": [
                        "number",
                        "array"
                    ]
                },
                "min": {
                    "type": "number"
                },
                "max": {
                    "type": "number"
                },
                "units": {
                    "type": "string"
                },
                "type": {
                    "type": "string"
                },
                "displayName": {
                    "type": "string"
                }
            }
        }
    },
    "type": "object",
    "additionalProperties": false,
    "required": [
        "config",
        "mutableConfigs"
    ],
    "properties": {
        "config": {
            "description": "Version-level pipette specifications, which may vary across different versions of the same pipette",
            "type": "object",
            "$comment": "Example key: 'p10_single_v1.3'",
            "patternProperties": {
                ".*": {
                    "required": [
                        "name",
                        "top",
                        "bottom",
                        "blowout",
                        "dropTip",
                        "pickUpCurrent",
                        "pickUpDistance",
                        "pickUpIncrement",
                        "pickUpPresses",
                        "pickUpSpeed",
                        "modelOffset",
                        "plungerCurrent",
                        "dropTipCurrent",
                        "dropTipSpeed",
                        "ulPerMm",
                        "tipLength"
                    ],
                    "additionalProperties": false,
                    "properties": {
                        "name": {
                            "description": "reference to name of this version, should match a key in corresponding pipetteNameSpecs.json file",
                            "type": "string"
                        },
                        "backCompatNames": {
                            "description": "Optional reference for name of backwards compatible pipette corresponding to a key in pipetteNameSpecs.json, only relevant to gen2 pipettes",
                            "type": "array"
                        },
                        "top": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "bottom": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "blowout": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "dropTip": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "pickUpCurrent": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "pickUpDistance": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "pickUpPresses": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "pickUpIncrement": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "pickUpSpeed": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "modelOffset": {
                            "$ref": "#/definitions/xyzArray"
                        },
                        "plungerCurrent": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "dropTipCurrent": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "dropTipSpeed": {
                            "$ref": "#/definitions/editConfigurations"
                        },
                        "ulPerMm": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/liquidHandlingSpecs"
                            }
                        },
                        "quirks": {
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        },
                        "tipLength": {
                            "type": "object",
                            "value": {
                                "$ref": "#/definitions/positiveNumber"
                            }
                        },
                        "idleCurrent": {
                            "$ref": "#/definitions/idleCurrentRange"
                        },
                        "returnTipHeight": {
                            "$ref": "#/definitions/returnTipHeightRange"
                        },
                        "tipOverlap": {
                            "type": "object",
                            "description": "Map of tip overlap values with defaults",
                            "required": [
                                "default"
                            ],
                            "$comment": "Other keys in here should be labware URIs",
                            "properties": {
                                "default": {
                                    "type": "number"
                                }
                            },
                            "additionalProperties": {
                                "type": "number"
                            }
                        }
                    }
                }
            }
        },
        "mutableConfigs": {
            "type": "array",
            "description": "Array of mutable configs for a given pipette",
            "items": {
                "type": "string"
            }
        },
        "validQuirks": {
            "type": "array",
            "description": "Array of valid quirks for a given pipette",
            "items": {
                "type": "string"
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Backend Config",
    "description": "A configuration file for the PrairieLearn server.",
    "type": "object",
    "properties": {
        "courseDirs": {
            "description": "Paths of the course directories.",
            "type": "array",
            "items": {
                "description": "A single course directory path.",
                "type": "string"
            }
        },
        "secretKey": {
            "description": "Secret key for authenticating users (should be a long random string).",
            "type": "string"
        },
        "postgresqlUser": {
            "description": "The user for connecting to the PostgreSQL database.",
            "type": "string"
        },
        "postgresqlDatabase": {
            "description": "The database for connecting to the PostgreSQL database.",
            "type": "string"
        },
        "postgresqlHost": {
            "description": "The host for connecting to the PostgreSQL database.",
            "type": "string"
        },
        "redisUrl": {
            "description": "The url for connecting to Redis.",
            "type": "string"
        },
        "logFilename": {
            "description": "Filename to use for server logging.",
            "type": "string"
        },
        "authType": {
            "description": "The type of authentication to use.",
            "enum": [
                "none",
                "x-auth",
                "eppn",
                "x-trust-auth"
            ]
        },
        "serverType": {
            "description": "The type of server to start.",
            "enum": [
                "http",
                "https"
            ]
        },
        "sslCertificateFile": {
            "description": "Path to SSL certificate",
            "type": "string"
        },
        "sslKeyFile": {
            "description": "Path to SSL certificate key file",
            "type": "string"
        },
        "sslCAFile": {
            "description": "Path to SSL CA chain file",
            "type": "string"
        },
        "serverPort": {
            "description": "The TCP port number for the server.",
            "type": "string"
        },
        "groupName": {
            "description": "The group of servers we belong to, used for load reporting and autoscaling.",
            "type": "string"
        },
        "blockedWarnEnable": {
            "description": "Whether to detect and warn on blockages in the event loop.",
            "type": "boolean"
        },
        "blockedAtWarnEnable": {
            "description": "Whether to use more expensive event-loop-blocking detection that includes stack traces (not for routine use in production).",
            "type": "boolean"
        },
        "blockedWarnThresholdMS": {
            "description": "The threshold (in milliseconds) for detecting event-loop blockages.",
            "type": "integer"
        },
        "checkAccessRulesExamUuid": {
            "description": "On sync, check if assessment access rules examUuid exists in database (default false)",
            "type": "boolean"
        },
        "cronIntervalMS": {
            "description": "Time between cron job runs (milliseconds).",
            "type": "integer"
        },
        "autoFinishAgeMins": {
            "description": "Time after last activity when exams are auto-closed (minutes).",
            "type": "integer"
        },
        "runningInEc2": {
            "description": "Whether PL is running as an AWS EC2 instance",
            "type": "boolean"
        },
        "externalGradingUseAws": {
            "description": "If the external grader should use AWS (production) or not (local dev).",
            "type": "boolean"
        },
        "externalGradingS3Bucket": {
            "description": "The S3 bucket that externally graded jobs should be stored in.",
            "type": "string"
        },
        "externalGradingResultsS3Bucket": {
            "description": "The S3 bucket where externally graded job results will be stored.",
            "type": "string"
        },
        "externalGradingJobQueue": {
            "description": "The name of the job queue where externally graded jobs will be submitted.",
            "type": "string"
        },
        "externalGradingJobRole": {
            "description": "The ARN of the role that should be provided to external grading containers for resource access.",
            "type": "string"
        },
        "externalGradingWebhookUrl": {
            "description": "The endpoint that should be hit when a grading result is updated. Should be null when running locally.",
            "type": "string"
        },
        "externalGradingDefaultTimeout": {
            "description": "The default timeout to use for external grading if none is specified by a question.",
            "type": "integer"
        },
        "externalGradingPullImagesFromDockerHub": {
            "description": "Whether externally graded questions should automatically pull container images from Docker Hub (true) or use only locally cached images (false)",
            "type": "boolean"
        },
        "awsRegion": {
            "description": "The region for AWS resources.",
            "type": "string"
        },
        "hasShib": {
            "description": "Enables Shibboleth authentication",
            "type": "boolean"
        },
        "hasAzure": {
            "description": "Enables Azure authentication",
            "type": "boolean"
        },
        "hasOauth": {
            "description": "Enables OAuth authentication",
            "type": "boolean"
        },
        "useWorkers": {
            "description": "Enable persistent, forking Python workers",
            "type": "boolean"
        },
        "workersCount": {
            "description": "The number of workers to use (or null to use workersPerCpu).",
            "type": "integer"
        },
        "workersPerCpu": {
            "description": "The number of workers per CPU (if workersCount is null).",
            "type": "number"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "debug": {
            "type": "boolean"
        },
        "delay": {
            "type": "number"
        },
        "gutter_theme": {
            "type": "string"
        },
        "highlights.time_to_idle": {
            "type": "number"
        },
        "highlights.demote_while_editing": {
            "type": "string",
            "enum": [
                "none",
                "ws_only",
                "some_ws",
                "multilines",
                "warnings",
                "all"
            ]
        },
        "kill_old_processes": {
